#include <stdio.h>
#include <string.h>

#define MAX_INPUT 0x400          /* 1024 characters */
#define OUT_BUF   (MAX_INPUT+1)  /* space for terminating NUL */

int main(int argc, char *argv[])
{
    const char *src;
    char out[OUT_BUF];
    size_t len, i, out_len = 0;
    int have_nonws = 0;          /* have we output any non‑whitespace yet? */
    int pending_space = 0;       /* need to insert a single space before next token */

    /* No argument -> print EMPTY */
    if (argc < 2) {
        puts("EMPTY");
        return 0;
    }

    src = argv[1];
    len = strlen(src);
    if (len > MAX_INPUT)          /* truncate to the first 1024 bytes */
        len = MAX_INPUT;

    /* Scan the input */
    for (i = 0; i < len; ++i) {
        char c = src[i];

        /* Is this character whitespace? */
        int is_ws = (c == ' '  || c == '\t' || c == '\n' ||
                     c == '\r' || c == '\v' || c == '\f');

        if (is_ws) {
            /* If we have already started output, remember that a space
               should be inserted before the next non‑whitespace character. */
            if (have_nonws)
                pending_space = 1;
            /* otherwise we are still in leading whitespace – ignore it */
            continue;
        }

        /* Non‑whitespace character */
        if (pending_space) {
            if (out_len < MAX_INPUT) {
                out[out_len++] = ' ';
            }
            pending_space = 0;
        }

        if (out_len < MAX_INPUT) {
            out[out_len++] = c;
        }
        have_nonws = 1;
    }

    /* Null‑terminate the output buffer */
    out[out_len] = '\0';

    /* If nothing was produced, print EMPTY */
    if (out_len == 0) {
        puts("EMPTY");
    } else {
        puts(out);
    }

    return 0;
}
